      IntervalIterator it = source.intervals("field", ctx);
      assertEquals(-1, it.docID());
      it.advance(1);
      assertEquals(DocIdSetIterator.NO_MORE_DOCS, it.docID());
    }

    reader.close();
    directory.close();
  }
